begin;
create function pg_temp.check_owner(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end$$;
create function pg_temp.expect_owner(statement text,code text,label text) returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate=code then raise notice 'PASS: %',label;return;end if;raise;end;raise exception 'FAIL: %',label;end$$;
insert into auth.users(id) values ('60090000-0000-4000-8000-000000000001'),('60090000-0000-4000-8000-000000000002');
insert into access_private.mutation_keys values('synthetic-test',decode(repeat('ab',32),'hex'));
create function pg_temp.owner_ticket(m jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare msg text;begin msg=(jsonb_build_object('keyId','synthetic-test','expires',floor(extract(epoch from clock_timestamp()))+120,'actor',auth.uid(),'inputHash','synthetic','module','synthetic','audit','{}'::jsonb)||m)::text;return public.commit_validated_owner_change(msg,encode(extensions.hmac(convert_to(msg,'UTF8'),decode(repeat('ab',32),'hex'),'sha256'),'hex'));end$$;
select set_config('request.jwt.claim.sub','60090000-0000-4000-8000-000000000001',true);
set local role authenticated;
select pg_temp.check_owner(not has_table_privilege('authenticated','access_private.mutation_keys','select') and not has_table_privilege('service_role','access_private.mutation_keys','select'),'signing keys are not readable by API roles');
select pg_temp.check_owner(not has_function_privilege('anon','public.commit_validated_owner_change(text,text)','execute'),'anonymous RPC execution denied');
select pg_temp.expect_owner($q$select public.commit_validated_owner_change('{}','bad')$q$,'42501','invalid signature denied');
select pg_temp.expect_owner($q$select pg_temp.owner_ticket('{"actor":"60090000-0000-4000-8000-000000000002"}')$q$,'42501','signed actor mismatch denied');
select pg_temp.expect_owner($q$select pg_temp.owner_ticket('{"expires":1}')$q$,'42501','expired ticket denied');
select pg_temp.expect_owner($q$select pg_temp.owner_ticket('{"expires":null}')$q$,'42501','missing ticket expiry denied');
select pg_temp.check_owner((pg_temp.owner_ticket('{"kind":"property","requestId":"create","property":{"id":"hu60-owner-sql","name":"Initial"}}')->>'replayed')::boolean=false,'signed property creation succeeds');
select pg_temp.check_owner((pg_temp.owner_ticket('{"kind":"property","requestId":"create","property":{"id":"hu60-owner-sql","name":"Initial"}}')->>'replayed')::boolean and (select count(*)=1 from public.audit_events where user_id=auth.uid()),'same request commits once');
select pg_temp.expect_owner($q$select pg_temp.owner_ticket('{"kind":"property","requestId":"create","inputHash":"changed","property":{"id":"hu60-owner-sql"}}')$q$,'40001','request identity cannot be reused for another input');
select pg_temp.expect_owner($q$select pg_temp.owner_ticket('{"kind":"property","requestId":"stale","property":{"id":"hu60-owner-sql"}}')$q$,'40001','stale property version denied');
select pg_temp.check_owner((pg_temp.owner_ticket(jsonb_build_object('kind','book','requestId','book','book','{"invoices":[{"id":"hu60-owner-invoice","declaredTotal":10,"lines":[{"id":"hu60-owner-line","subtotal":10,"tax":0,"retention":0,"included":0,"propertyId":"hu60-owner-sql","classification":{"splits":[{"subtotal":10,"tax":0}]}}]}]}'::jsonb,'storedBook','{"invoiceStorage":1}'::jsonb,'properties',(select jsonb_agg(jsonb_build_object('id',id,'version',updated_at)) from public.properties)))->>'version') is not null,'normalized book commits');
select pg_temp.check_owner((select count(*)=1 from public.expense_invoices where user_id=auth.uid()) and (select count(*)=1 from public.expense_lines where user_id=auth.uid()) and (select count(*)=1 from public.expense_allocations where user_id=auth.uid()),'invoice line and allocation persisted together');
reset role;
create function pg_temp.owner_audit_failure() returns trigger language plpgsql as $$begin if new.id like '%:fail' then raise exception using errcode='P0001',message='synthetic failure';end if;return new;end$$;
create trigger owner_audit_failure before insert on public.audit_events for each row execute function pg_temp.owner_audit_failure();
set local role authenticated;
select pg_temp.expect_owner($q$select pg_temp.owner_ticket(jsonb_build_object('kind','book','requestId','fail','bookVersion',(select updated_at from public.accounting_books),'properties',(select jsonb_agg(jsonb_build_object('id',id,'version',updated_at)) from public.properties),'book','{"invoices":[]}'::jsonb,'storedBook','{"invoiceStorage":1}'::jsonb))$q$,'P0001','injected audit failure propagates');
select pg_temp.check_owner((select count(*)=1 from public.expense_invoices where user_id=auth.uid()) and (select count(*)=1 from public.expense_lines where user_id=auth.uid()) and (select count(*)=1 from public.expense_allocations where user_id=auth.uid()),'audit failure rolls back all normalized deletions');
select set_config('request.jwt.claim.sub','60090000-0000-4000-8000-000000000002',true);
select pg_temp.expect_owner($q$select pg_temp.owner_ticket('{"kind":"property","requestId":"other","property":{"id":"hu60-owner-sql"}}')$q$,'42501','other owner cannot claim property');
reset role;
rollback;
